so_('a Penal Code section in the wrong Act', 'Women\'s Charter 1961', '376')
o.assert_("`the class of the offence under the First Schedule` `a Penal Code section in the wrong Act` EQUALS `neither`")
o.assert_("`the offence is a child abuse offence under section 3(1)` `PC s 377BG`")
o.assert_("NOT `the offence is a child abuse offence under section 3(1)` `PC s 375`")
o.assert_("`the offence is a sexual offence under section 3(1)` `PC s 375`")
o.assert_("NOT `the offence is a sexual offence under section 3(1)` `PC s 377BG`")

o.section('Second Schedule. Specified statutory bodies')
for name in ['Building and Construction Authority', 'Central Provident Fund Board', 'Civil Aviation Authority of Singapore', 'Civil Service College', 'Defence Science and Technology Agency', 'Enterprise Singapore Board', 'Economic Development Board', 'Health Sciences Authority', 'Home Team Science and Technology Agency', 'Housing and Development Board', 'Info-communications Media Development Authority', 'Inland Revenue Authority of Singapore', 'Intellectual Property Office of Singapore', 'Jurong Town Corporation', 'Land Transport Authority of Singapore', 'Maritime and Port Authority of Singapore', 'Monetary Authority of Singapore', 'National Parks Board', 'Public Utilities Board', 'Singapore Food Agency', 'Singapore Land Authority', 'Singapore Tourism Board', 'Urban Redevelopment Authority']:
    o.assert_('`the body is a specified statutory body in the Second Schedule` "%s"' % name)
o.assert_('NOT `the body is a specified statutory body in the Second Schedule` "Singapore Airlines"')
o.assert_('NOT `the body is a specified statutory body in the Second Schedule` "Accounting and Corporate Regulatory Authority"')

o.section('The principal questions and the conclusions for the Code')
def bundle(var, prev, imp, hear, form, adm, op, acc):
    o.raw("`%s` MEANS `Evidence Act Fact Bundle` WITH\n    `previous statement facts` IS `%s`\n    `impeachment and corroboration facts` IS `%s`\n    `hearsay facts` IS `%s`\n    `former testimony facts` IS `%s`\n    `admission facts` IS `%s`\n    `opinion facts` IS `%s`\n    `accused cross-examination facts` IS `%s`" % (var, prev, imp, hear, form, adm, op, acc))
o.case('no previous statement', 'Previous Statement Facts')
o.case('no impeachment', 'Impeachment and Corroboration Facts')
o.case('no hearsay ground', 'Hearsay Facts', **{KP: 'criminal proceedings'})
o.case('no former testimony', 'Former Testimony Facts')
o.case('no admission', 'Admission Facts')
o.case('no expert opinion', 'Opinion Facts')
o.case('no question to the accused', 'Accused Cross-examination Facts')
o.case('a witness contradicted by a written statement', 'Previous Statement Facts', 'previous statement was made in writing or reduced into writing', 'relevant to matters in question', 'intended to contradict the witness by the writing', 'attention was called', 'direct oral evidence of the fact stated by the maker would be admissible')
o.case('a witness impeached by the adverse party', 'Impeachment and Corroboration Facts', 'impeached by the adverse party', 'former statements inconsistent')
o.case('a dying person\'s statement', 'Hearsay Facts', 'the statement was made by a person, whether orally, in a document or otherwise', 'the statement is of a relevant fact', 'statement is made by a person as to the cause of that person', 'death comes into question', **{KP: 'criminal proceedings'})
o.case('a statement of a person who cannot be found', 'Hearsay Facts', 'the statement was made by a person, whether orally, in a document or otherwise', 'the statement is of a relevant fact', 'cannot be found', **{KP: 'criminal proceedings'})
o.case('an expert whose help the court needs', 'Opinion Facts', 'likely to derive assistance', 'scientific, technical or other specialised knowledge based on training')
o.case('a question about the accused\'s other offences', 'Accused Cross-examination Facts', 'accused gives evidence', 'committed, or has been charged with or convicted or acquitted of, an offence other than')
o.case('a party admitting a fact', 'Admission Facts', 'oral or documentary', 'suggests an inference', 'maker is a party to the proceeding', 'sought to be proved against the maker')
bundle('empty bundle', 'no previous statement', 'no impeachment', 'no hearsay ground', 'no former testimony', 'no admission', 'no expert opinion', 'no question to the accused')
bundle('bundle: contradicted by a writing', 'a witness contradicted by a written statement', 'no impeachment', 'no hearsay ground', 'no former testimony', 'no admission', 'no expert opinion', 'no question to the accused')
bundle('bundle: impeached', 'no previous statement', 'a witness impeached by the adverse party', 'no hearsay ground', 'no former testimony', 'no admission', 'no expert opinion', 'no question to the accused')
bundle('bundle: dying statement', 'no previous statement', 'no impeachment', 'a dying person\'s statement', 'no former testimony', 'no admission', 'no expert opinion', 'no question to the accused')
bundle('bundle: absent maker', 'no previous statement', 'no impeachment', 'a statement of a person who cannot be found', 'no former testimony', 'no admission', 'no expert opinion', 'no question to the accused')
bundle('bundle: expert', 'no previous statement', 'no impeachment', 'no hearsay ground', 'no former testimony', 'no admission', 'an expert whose help the court needs', 'no question to the accused')
bundle('bundle: question to the accused', 'no previous statement', 'no impeachment', 'no hearsay ground', 'no former testimony', 'no admission', 'no expert opinion', 'a question about the accused\'s other offences')
bundle('bundle: party admission', 'no previous statement', 'no impeachment', 'no hearsay ground', 'no former testimony', 'a party admitting a fact', 'no expert opinion', 'no question to the accused')
C = '`the Code says the notice conditions are met and sections 265 and 266 do not apply`'
CN = '`the Code says sections 265 or 266 make the evidence admissible`'
# an empty bundle yields no Evidence Act conclusion
for field in ['the statement is admitted under section 147 of the Evidence Act 1893', 'the statement is used for impeaching credit in the manner provided in section 157 of the Evidence Act 1893', 'the statement is made admissible in criminal proceedings by another provision of the Evidence Act 1893', 'the statement falls within section 32(1)(a) of the Evidence Act 1893', 'the statement is admissible as evidence of a fact stated in it under the Evidence Act 1893', 'the opinion of an expert is admissible under the Evidence Act 1893', 'the accused is entitled by section 122(4) of the Evidence Act 1893 to refuse to answer the question']:
    o.assert_("NOT (`the Evidence Act conclusions on an item of evidence` `empty bundle` %s)'s `%s`" % (C, field))
def concl(b, field, c=C, neg=False):
    o.assert_("%s(`the Evidence Act conclusions on an item of evidence` `%s` %s)'s `%s`" % ('NOT ' if neg else '', b, c, field))
F147 = 'the statement is admitted under section 147 of the Evidence Act 1893'
F157 = 'the statement is used for impeaching credit in the manner provided in section 157 of the Evidence Act 1893'
FOTH = 'the statement is made admissible in criminal proceedings by another provision of the Evidence Act 1893'
F32A = 'the statement falls within section 32(1)(a) of the Evidence Act 1893'
FEVI = 'the statement is admissible as evidence of a fact stated in it under the Evidence Act 1893'
FEXP = 'the opinion of an expert is admissible under the Evidence Act 1893'
F122 = 'the accused is entitled by section 122(4) of the Evidence Act 1893 to refuse to answer the question'
concl('bundle: contradicted by a writing', F147)
concl('bundle: contradicted by a writing', FEVI)
concl('bundle: contradicted by a writing', FOTH)
concl('bundle: contradicted by a writing', F157, neg=True)
concl('bundle: impeached', F157)
concl('bundle: impeached', F147, neg=True)
concl('bundle: impeached', FEVI, neg=True)
concl('bundle: dying statement', F32A)
concl('bundle: dying statement', FOTH)
concl('bundle: dying statement', FEVI)
concl('bundle: dying statement', F147, neg=True)
concl('bundle: absent maker', F32A, neg=True)
concl('bundle: absent maker', FEVI)
concl('bundle: absent maker', FOTH)
concl('bundle: absent maker', FEVI, c=C.replace('the Code says the notice conditions are met and sections 265 and 266 do not apply', "the Code says sections 265 or 266 make the evidence admissible"), neg=True)
concl('bundle: expert', FEXP)
concl('bundle: expert', FEVI, neg=True)
concl('bundle: question to the accused', F122)
concl('bundle: question to the accused', F122, c=CN, neg=True)
concl('bundle: party admission', FEVI)
concl('bundle: party admission', FOTH)
# the exported questions
o.assert_("`is the statement relevant under the Evidence Act` `bundle: dying statement` %s" % C)
o.assert_("NOT `is the statement relevant under the Evidence Act` `empty bundle` %s" % C)
o.assert_("`is the question forbidden by section 122(4)` `a question about the accused's other offences` %s" % C)
o.assert_("NOT `is the question forbidden by section 122(4)` `a question about the accused's other offences` %s" % CN)
o.case('a fact in issue', 'Relevancy Facts', 'the fact is a fact in issue')
o.case('a fact in no way relevant', 'Relevancy Facts')
o.assert_("`may evidence be given of the fact` `a fact in issue`")
o.assert_("NOT `may evidence be given of the fact` `a fact in no way relevant`")
o.case('a lost original', 'Document Facts', 'destroyed or lost')
o.case('an original in the court', 'Document Facts', 'the document itself is produced')
o.assert_("`may secondary evidence be given of the document` `a lost original`")
o.assert_("NOT `may secondary evidence be given of the document` `an original in the court`")
o.case('an accused relying on a Penal Code exception', 'Burden Facts', 'person is accused of an offence', 'general exception in the Penal Code')
o.case('a prosecution asserting the offence', 'Burden Facts', 'would fail if no evidence at all were given on either side is the party who asserts')
o.assert_("`is the burden on the accused under section 107` `an accused relying on a Penal Code exception`")
o.assert_("NOT `is the burden on the accused under section 107` `a prosecution asserting the offence`")
o.write(os.path.join(ROW, 'ea-tests-schedules-goals.l4'))
